from html.parser import HTMLParser

class Validator(HTMLParser):
    def __init__(self):
        super().__init__()
        self.tags = []
        self.errors = []
        self.img_count = 0
        self.has_doctype = False
    def handle_starttag(self, tag, attrs):
        if tag not in ['img', 'br', 'hr', 'meta', 'link', 'input']:
            self.tags.append(tag)
        if tag == 'img':
            self.img_count += 1
    def handle_endtag(self, tag):
        if tag not in ['img', 'br', 'hr', 'meta', 'link', 'input']:
            if self.tags and self.tags[-1] == tag:
                self.tags.pop()
            else:
                self.errors.append(f'Unexpected closing tag: {tag}')

with open('output/final_report.html', 'r') as f:
    content = f.read()

# Check doctype
if content.strip().upper().startswith('<!DOCTYPE HTML>'):
    print('Has DOCTYPE: yes')
else:
    print('Has DOCTYPE: no')

v = Validator()
v.feed(content)
print('Unclosed tags:', v.tags)
print('HTML errors:', v.errors)
print('Image count:', v.img_count)
print('File size (KB):', round(len(content)/1024, 1))
